impl CleanupPlace {
    fn whole(storage: StorageId) -> Self {
        Self {
            storage,
            projections: Vec::new(),
        }
    }

    fn projected(&self, projection: DeclarationId) -> Self {
        let mut projections = self.projections.clone();
        projections.push(projection);
        Self {
            storage: self.storage.clone(),
            projections,
        }
