                        function,
                        paths,
                        value_id,
                        destination,
                        "owned record field",
                        work,
                    )?;
                }
                let next = index + 1;
                if has_active_paths(&paths) && next < fields.len() {
                    push_frame!(
                        frames,
                        Frame::RecordField {
                            expression,
                            fields,
                            index: next,
                            paths,
                        }
