}

fn note_skeleton_materialization() {
    #[cfg(test)]
    SKELETON_MATERIALIZATIONS.with(|count| count.set(count.get().saturating_add(1)));
}

#[cfg(test)]
fn reset_skeleton_materializations() {
    SKELETON_MATERIALIZATIONS.with(|count| count.set(0));
}

