#[derive(Default)]
struct Automaton {
    nodes: Vec<Node>,
}

enum BuildFrame<'d> {
    Visit(&'d Rc<ObservationDag>, usize),
    Seq(&'d Rc<ObservationDag>, usize),
    Cat(&'d Rc<ObservationDag>, usize, usize),
    Alt(&'d Rc<ObservationDag>, usize, usize),
