                    return Err(fmt::Error);
                }
                match self
                    .output
                    .append(value, self.pay, self.logical, self.strict)
                {
                    Ok(true) => Ok(()),
                    Ok(false) => {
                        self.logical_refusal = true;
                        if self.strict {
                            Err(fmt::Error)
                        } else {
                            Ok(())
                        }
                    }
                    Err(error) => {
                        self.physical = Some(error);
                        Err(fmt::Error)
                    }
                }
            }
        }
        let mut writer = Writer {
            output: self,
            pay,
            strict,
            logical,
            logical_refusal: false,
            physical: None,
        };
