            || argument.ty != ResolvedType::String
            || argument.ownership != OwnershipMode::Own
            || !matches!(&argument.kind,ResolvedExprKind::Place(place) if place.projections.is_empty())
        {
            return Ok(None);
        }
    }
    Ok(Some(args))
}
