) -> Result<Option<&'a [ResolvedExpr]>, crate::hir::funded::FundedError<E>> {
    use crate::hir::funded::work as paid;
    paid::tick(work, 1)?;
    let ResolvedExprKind::Call {
        callee,
        type_arguments,
        instance,
        args,
    } = &expression.kind
    else {
