fn minimum_successful_builder_limit(sources: &[WorkspaceSource]) -> usize {
    assert!(build_owned_with_builder_limit(sources.to_vec(), MAX_BUILDER_BYTES).is_ok());
    let mut low = 0usize;
    let mut high = MAX_BUILDER_BYTES;
    while low < high {
