}
fn print_operation_receipt(profile: &str) {
    let trace = crate::bounded_output::stage_debits::take_completed();
    eprintln!(
        "validation-operation-receipt profile={profile} cap={MAX_BUILDER_BYTES} trace={trace:?}"
    );
